"""A GIF played by the device: frames encoded and read back (each frame, its size, its delay), a GIF file fitted
to the matrix, the name a segment takes, and the sending against a stand-in WLED on this machine - the file
uploaded whole, the segment set to the Image effect naming it; an ESP8266, a full filesystem and a WLED without
the effect refused."""
# AI: below section was generated by an AI
import io
import json
import os
import sys
import tempfile
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import numpy as np
from PIL import Image, ImageSequence

from native import devicegif as dg

fails = []


def check(ok, what):
    print(("ok   " if ok else "FAIL ") + what)
    if not ok:
        fails.append(what)


# frames: 12 of a 16 x 8 matrix, each its own colour block moving
frames = []
for k in range(12):
    f = np.zeros((8, 16, 3), np.uint8)
    f[:, k:k + 4] = (255, 40 * (k % 6), 0)
    frames.append(f)
data = dg.encode(frames, 20)
im = Image.open(io.BytesIO(data))
back = [np.asarray(fr.convert("RGB")) for fr in ImageSequence.Iterator(im)]
check(len(back) == 12 and back[0].shape == (8, 16, 3), f"12 frames of 16 x 8 back ({len(back)})")
check(all(np.abs(back[k].astype(int) - frames[k]).max() <= 8 for k in range(12)), "each frame as it was")
check(im.info.get("duration") == 50 and im.info.get("loop") == 0, f"50 ms a frame, looping ({im.info})")

check(dg.clean_name("My Show!.gif") == "MyShow.gif" and dg.clean_name("") == "studio.gif"
      and len(dg.clean_name("x" * 80)) <= 30, "names a segment takes")

# a GIF file fitted to the matrix: a 64 x 64 one of 5 frames at 100 ms
tmp = tempfile.mkdtemp()
src = os.path.join(tmp, "in.gif")
big = [Image.new("RGB", (64, 64), (k * 50, 0, 255 - k * 50)) for k in range(5)]
big[0].save(src, save_all=True, append_images=big[1:], duration=100, loop=0)
fr, fps = dg.from_file(src, 16, 8)
check(len(fr) == 5 and fr[0].shape == (8, 16, 3) and abs(fps - 10.0) < 0.01, f"a GIF fitted: {len(fr)} frames, {fps} fps")
still = os.path.join(tmp, "still.png")
Image.new("RGB", (30, 20), (0, 200, 0)).save(still)
fr, fps = dg.from_file(still, 16, 8)
check(len(fr) == 1 and tuple(fr[0][4, 8]) == (0, 200, 0), "a still picture: one frame")


# a stand-in WLED: what it was sent kept
class Fake:
    arch = "esp32"
    fs = {"u": 100, "t": 1400}
    effects = ["Solid", "Blink", "Image@!,Blur,;;;12;sx=128,ix=0", "Rainbow"]
    uploads = []
    states = []


class H(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def _json(self, v):
        b = json.dumps(v).encode()
        self.send_response(200); self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(b))); self.end_headers(); self.wfile.write(b)

    def do_GET(self):
        if self.path == "/json/info":
            self._json({"arch": Fake.arch, "fs": Fake.fs, "ver": "16.0.0"})
        elif self.path == "/json/effects":
            self._json(Fake.effects)
        elif self.path == "/json/state":
            self._json({"on": False, "mainseg": 1, "seg": [{"id": 0}, {"id": 1}]})
        else:
            self.send_response(404); self.end_headers()

    def do_POST(self):
        body = self.rfile.read(int(self.headers.get("Content-Length", 0)))
        if self.path == "/upload":
            head, _, rest = body.partition(b"\r\n\r\n")
            name = head.split(b'filename="', 1)[1].split(b'"', 1)[0].decode()
            payload = rest.rsplit(b"\r\n--", 1)[0]
            Fake.uploads.append((name, payload))
            self.send_response(200); self.end_headers(); self.wfile.write(b"ok")
        elif self.path == "/json/state":
            Fake.states.append(json.loads(body))
            self._json({"success": True})


srv = ThreadingHTTPServer(("127.0.0.1", 0), H)
threading.Thread(target=srv.serve_forever, daemon=True).start()
host = f"127.0.0.1:{srv.server_address[1]}"

ok, words = dg.send(host, data, "loop.gif")
check(ok, "sent: " + words)
check(Fake.uploads and Fake.uploads[-1] == ("/loop.gif", data), "the file uploaded whole as /loop.gif")
check(Fake.states and Fake.states[-1] == {"on": True, "seg": [{"id": 1, "fx": 2, "n": "loop.gif", "sx": 128, "ix": 0}]},
      f"the main segment set to Image naming it ({Fake.states[-1] if Fake.states else None})")

Fake.fs = {"u": 1380, "t": 1400}
n = len(Fake.uploads)
ok, words = dg.send(host, data, "loop.gif")
check(not ok and "room" in words and len(Fake.uploads) == n, "a full filesystem refused before sending: " + words)
Fake.fs = {"u": 100, "t": 1400}
Fake.arch = "esp8266"
ok, words = dg.send(host, data, "loop.gif")
check(not ok and "ESP8266" in words, "an ESP8266 refused: " + words)
Fake.arch = "esp32"
Fake.effects = ["Solid", "Rainbow"]
ok, words = dg.send(host, data, "loop.gif")
check(not ok and "Image" in words, "a WLED without the Image effect refused: " + words)
ok, words = dg.send("", data, "loop.gif")
check(not ok, "no device: refused")
srv.shutdown()

print("FAILED:", fails if fails else "none")
sys.exit(1 if fails else 0)
# AI: end
